async (page) => {
  const results=[];const check=(ok,label)=>{if(!ok)throw Error(label);results.push(label)};
  await page.getByRole('button',{name:'Studio',exact:true}).click();
  await page.getByRole('button',{name:'Add a component',exact:true}).click();await page.getByRole('button',{name:'Project',exact:true}).click();await page.getByRole('button',{name:'People',exact:true}).click();
  check(await page.locator('.directory-row').count()===4,'Shared project exposes its four sample members and their roles');
  await page.getByRole('button',{name:'general',exact:true}).click();
  await page.getByRole('button',{name:'1 reply',exact:true}).click();
  await page.getByRole('textbox',{name:'Thread reply',exact:true}).fill('Keep the source trail in this thread.');
  await page.getByRole('button',{name:'Send message',exact:true}).click();
  check((await page.locator('.thread-view').innerText()).includes('Keep the source trail'),'Thread reply is shown under its parent message');
  await page.getByRole('button',{name:'Back to channel',exact:true}).click();
  check(!((await page.locator('.conversation .module-body').innerText()).includes('Keep the source trail')),'Thread reply is not duplicated as a top-level message');
  await page.getByRole('button',{name:'New project channel',exact:true}).click();
  await page.getByRole('textbox',{name:'New channel',exact:true}).fill('review-notes');
  await page.getByRole('button',{name:'Create',exact:true}).click();
  check(await page.getByRole('textbox',{name:'Message review-notes',exact:true}).count()===1,'New channel becomes the composer target');
  await page.getByRole('button',{name:'My workspace',exact:true}).click();
  await page.getByRole('button',{name:'New private chat',exact:true}).click();
  await page.getByRole('textbox',{name:'New private chat',exact:true}).fill('Personal exploration');
  await page.getByRole('button',{name:'Create',exact:true}).click();
  await page.getByRole('textbox',{name:'Message Personal exploration',exact:true}).fill('A private chat entry.');
  await page.getByRole('button',{name:'Send message',exact:true}).click();
  check(await page.locator('.conversation').count()===1,'Private chat remains a conversation rather than a document');
  await page.getByRole('button',{name:'My workspace',exact:true}).click();
  await page.getByRole('button',{name:'Add a component',exact:true}).click();
  await page.getByRole('button',{name:'Document',exact:true}).click();
  await page.getByRole('textbox',{name:'Resource name',exact:true}).dblclick();
  await page.getByRole('textbox',{name:'Resource name',exact:true}).fill('Canonical sharing check');
  await page.getByRole('textbox',{name:'Document content',exact:true}).fill('Version one.');
  await page.getByRole('button',{name:'History',exact:true}).click();
  await page.getByText('Read this version',{exact:true}).first().click();
  check((await page.locator('.history-entry').first().innerText()).includes('Version one.'),'History retains a readable content snapshot');
  await page.getByRole('button',{name:'Sharing',exact:true}).click();
  const identity=await page.locator('[data-share]').getAttribute('data-share');
  await page.getByRole('button',{name:'Share original',exact:true}).click();
  check(await page.locator(`[data-resource="${identity}"]`).count()===0,'Sharing removes the original from private resources');
  await page.getByRole('button',{name:'Studio',exact:true}).click();
  await page.getByRole('button',{name:'Add a component',exact:true}).click();await page.getByRole('button',{name:'Files',exact:true}).click();
  await page.locator(`[data-inline-resource="${identity}"]`).click();
  check((await page.locator('.resource-name').inputValue())==='Canonical sharing check','Shared project exposes the same canonical resource identity');
  await page.getByRole('button',{name:'Sharing',exact:true}).click();
  await page.getByRole('button',{name:'Create a private variant',exact:true}).click();
  await page.getByRole('button',{name:'My workspace',exact:true}).click();
  await page.getByRole('button',{name:'Add a component',exact:true}).click();await page.getByRole('button',{name:'Files',exact:true}).click();
  const variant=page.locator('[data-inline-resource]').filter({hasText:'Canonical sharing check · variant'});
  check(await variant.count()===1,'Private variant appears as a separate resource');
  check(await variant.getAttribute('data-inline-resource')!==identity,'Variant has a distinct identity');
  await variant.click();
  await page.getByRole('button',{name:'History',exact:true}).click();
  check((await page.locator('.module-body').last().innerText()).includes('Private variant of Canonical sharing check'),'Variant history retains ancestry');
  await page.getByRole('button',{name:'New shared project',exact:true}).click();
  await page.getByRole('textbox',{name:'New shared project',exact:true}).fill('New project check');
  await page.getByRole('button',{name:'Create',exact:true}).click();
  await page.getByRole('button',{name:'Add a component',exact:true}).click();await page.getByRole('button',{name:'Project',exact:true}).click();await page.getByRole('button',{name:'Agents',exact:true}).click();check((await page.locator('.directory-list').innerText()).includes('Project agent'),'New project receives a dedicated agent assignment');
  check(await page.getByRole('button',{name:'general',exact:true}).count()===1&&await page.getByRole('button',{name:'references',exact:true}).count()===1,'New project initializes its channels');
  await page.getByRole('button',{name:'Goals',exact:true}).click();
  await page.getByRole('textbox',{name:'New milestone',exact:true}).fill('Make the next step clear');
  await page.getByRole('button',{name:'Add milestone',exact:true}).click();
  await page.getByRole('combobox',{name:'Agent assignment',exact:true}).selectOption('yes');
  await page.getByRole('textbox',{name:'Deadline',exact:true}).fill('2026-11-02');
  await page.reload();
  check(await page.getByRole('combobox',{name:'Agent assignment',exact:true}).inputValue()==='yes','Milestone agent assignment survives reload');
  check(await page.getByLabel('Deadline',{exact:true}).inputValue()==='2026-11-02','Milestone deadline survives reload');
  return results;
}
